<template><view class="page"><view class="period-tabs"><view :class="period==='day'?'active':''" @click="period='day'">日</view><view :class="period==='week'?'active':''" @click="period='week'">周</view><view :class="period==='total'?'active':''" @click="period='total'">总览</view></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/><template v-else-if="data"><view class="muted plan-name">{{plan.examName}}</view><view class="stats-grid"><view class="card stat"><view class="stat-icon green">◷</view><view><view class="muted">今日学习</view><view class="value">{{Math.floor(todayMinutes/60)}}<text>小时</text>{{todayMinutes%60}}<text>分钟</text></view></view></view><view class="card stat"><view class="stat-icon orange">♨</view><view><view class="muted">连续打卡</view><view class="value">{{data.streak}}<text>天</text></view></view></view><view class="card stat"><view class="stat-icon blue">▥</view><view><view class="muted">累计学习</view><view class="value">{{(data.minutes/60).toFixed(1)}}<text>小时</text></view></view></view><view class="card stat"><view class="stat-icon green">✓</view><view><view class="muted">今日完成</view><view class="value">{{done}}/{{tasks.length}}</view></view></view></view><view class="section row"><text>学习时长趋势</text><text class="muted">分钟</text></view><view class="card chart-card"><view class="chart"><view v-for="d in days" :key="d.date" class="bar-column"><text class="bar-value">{{d.minutes}}</text><view class="bar-space"><view class="bar" :style="{height:Math.max(4,d.minutes/max*135)+'px'}"/></view><text class="bar-date">{{d.date.slice(5).replace('-','.')}}</text></view></view><view class="muted chart-note">{{period==='day'?'今日打卡时长':'最近七天的实际打卡时长'}}</view></view><view class="section">科目学习分布</view><view class="card"><view v-if="!data.subjects.length" class="muted">完成任务后，学习进步会记录在这里。</view><view v-for="s in data.subjects" :key="s.name" class="subject"><view class="row"><text>{{s.name}}</text><text class="muted">{{s.minutes}}分钟</text></view><view class="progress"><view class="fill" :style="{width:(data.minutes?s.minutes/data.minutes*100:0)+'%'}"/></view></view></view><view class="muted foot">时长按已完成任务的计划分钟统计，连续天数按实际打卡日期计算。</view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,current} from '../../api';import {today} from '../../utils/planner.mjs';import EmptyState from '../../components/EmptyState.vue'
const plan=ref(null),data=ref(null),tasks=ref([]),loading=ref(true),error=ref(''),period=ref('week'),days=computed(()=>data.value?(period.value==='day'?data.value.week.filter(d=>d.date===today()):data.value.week):[]),max=computed(()=>Math.max(1,...days.value.map(d=>d.minutes))),todayMinutes=computed(()=>data.value?.week.find(d=>d.date===today())?.minutes||0),done=computed(()=>tasks.value.filter(t=>t.completed).length)
async function load(){loading.value=true;error.value='';try{plan.value=await current();if(plan.value)[data.value,tasks.value]=await Promise.all([api.records(plan.value.id),api.tasks(plan.value.id)])}catch(e){error.value=e.message}finally{loading.value=false}}onShow(load)
</script>
<style scoped>.period-tabs{display:flex;margin:4rpx 0 22rpx;text-align:center;color:#7A9085;gap:20rpx;font-size:25rpx}.period-tabs view{flex:1;padding:8rpx;border-radius:35rpx}.period-tabs .active{background:linear-gradient(110deg,#1DB699,#0BBC7D);color:white;font-weight:650}.plan-name{margin-bottom:20rpx;font-size:23rpx}.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx}.stat{display:flex;align-items:center;gap:14rpx;padding:24rpx 16rpx;margin:0}.stat-icon{width:56rpx;height:56rpx;flex-shrink:0;border-radius:50%;line-height:56rpx;text-align:center;font-size:32rpx;font-weight:750}.green{color:#19AF88;background:#EAF9F1}.orange{color:#FF9E29;background:#FFF4E4}.blue{color:#5C88FF;background:#EEF2FF}.stat .muted{font-size:22rpx}.value{font-size:34rpx;font-weight:800;line-height:1.35;white-space:nowrap}.value text{font-weight:500;font-size:19rpx;margin:0 5rpx}.section{font-size:30rpx}.section .muted{font-size:21rpx}.chart-card{padding:26rpx 22rpx}.chart{display:flex;justify-content:space-around;align-items:flex-end;gap:12rpx}.bar-column{flex:1;text-align:center;max-width:100rpx}.bar-value{font-size:19rpx;color:#82998D}.bar-space{height:150px;display:flex;align-items:flex-end;justify-content:center;margin:8rpx 0}.bar{width:30rpx;max-height:135px;background:linear-gradient(180deg,#B9EFD6,#33C496);border-radius:20rpx 20rpx 10rpx 10rpx}.bar-date{color:#80938A;font-size:20rpx}.chart-note{text-align:center;font-size:20rpx;margin-top:22rpx}.subject{margin:12rpx 0 26rpx;font-size:25rpx}.subject:last-child{margin-bottom:6rpx}.subject .muted{font-size:22rpx}.foot{font-size:21rpx}</style>
